import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BjM_ivYE.js";const n="/RBQ/images/app/home-ptz.pc.en.png",u=JSON.parse('{"title":"PTZ camera","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/ptz.md","filePath":"manual/gui/ptz.md","lastUpdated":1790646319000}'),i={name:"manual/gui/ptz.md"};function s(c,e,h,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ptz-camera" tabindex="-1">PTZ camera <a class="header-anchor" href="#ptz-camera" aria-label="Permalink to &quot;PTZ camera&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This panel appears only on robots fitted with the optional PTZ camera unit. <code>CCTV</code> is listed when the robot reports the PTZ color camera. <code>Thermal</code> and <code>PTZ Mix</code> also need the thermal sensor, so a PTZ unit without one shows <code>CCTV</code> only. If all three are missing from the viewport source list, no PTZ unit was detected.</p></div><h2 id="opening-the-panel" tabindex="-1">Opening the panel <a class="header-anchor" href="#opening-the-panel" aria-label="Permalink to &quot;Opening the panel&quot;">​</a></h2><p>There is no separate PTZ screen. Switch the viewport source to <code>CCTV</code>, <code>Thermal</code>, or <code>PTZ Mix</code> and the PTZ control panel floats over the video. Switch to any other source and it disappears. You control the camera while looking at its picture.</p><h2 id="pan-tilt" tabindex="-1">Pan / tilt <a class="header-anchor" href="#pan-tilt" aria-label="Permalink to &quot;Pan / tilt&quot;">​</a></h2><p><img src="'+n+'" alt="PTZ panel over the viewport"></p><p>Drag the small joystick at the top of the panel to move the camera: left/right pans, up/down tilts. The camera keeps moving as long as you hold the stick and stops when you release it. Use small, slow inputs to settle on a target. The <code>Sensitivity</code> slider at the bottom of the panel — default 60 %, minimum 10 % — scales the stick output. It stays separate from the robot&#39;s own joystick sensitivity because gimbal work needs finer steps.</p><h2 id="zoom" tabindex="-1">Zoom <a class="header-anchor" href="#zoom" aria-label="Permalink to &quot;Zoom&quot;">​</a></h2><p>Optical zoom has five fixed steps — the camera does not accept values in between:</p><ul><li><code>1x</code>, <code>3x</code>, <code>8x</code>, <code>16x</code>, <code>32x</code> — tap a step button to jump straight to it.</li><li>The <code>Zoom</code> slider above the buttons scrubs through the same five steps, and the current step appears to its right.</li></ul><h2 id="center" tabindex="-1">Center <a class="header-anchor" href="#center" aria-label="Permalink to &quot;Center&quot;">​</a></h2><p><code>Center</code> returns the camera to its home position: pan and tilt to the middle of their range and zoom fully out. The <code>Zoom</code> slider and step buttons do not follow this reset — tap <code>1x</code> if you want the panel to match the camera again. Use it when you have lost track of where the camera is pointing.</p><h2 id="face-temperature" tabindex="-1">Face temperature <a class="header-anchor" href="#face-temperature" aria-label="Permalink to &quot;Face temperature&quot;">​</a></h2><p>On the <code>PTZ Mix</code> source only, a <code>FaceTemp OFF</code> / <code>FaceTemp ON</code> button appears next to <code>Center</code>. Turn it on to read the temperature of detected faces from the combined color + thermal view. Switching to any other source turns it off automatically.</p><h2 id="moving-the-panel" tabindex="-1">Moving the panel <a class="header-anchor" href="#moving-the-panel" aria-label="Permalink to &quot;Moving the panel&quot;">​</a></h2><p>The panel starts to the left of the <code>PTZ</code> row in the OBSERVE card, so it is next to the button that opens it. Drag it by the handle in its top-right corner to any spot that does not hide what you need to see — the bottom corners are reserved for the virtual joysticks. On a short screen the panel is pulled back inside the viewport, because a handle off the screen would leave you no way to move it.</p>',16)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
